"use client";
import { useEffect } from "react";
export default function ErrorPage({
  reset,
  error,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // The digest is generated by Next; avoid logging the exception message or user data.
    const digest =
      error.digest && /^[a-zA-Z0-9_-]{1,80}$/.test(error.digest) ? error.digest : "unavailable";
    console.error(`Page failed (digest: ${digest})`);
  }, [error]);
  return (
    <main className="mx-auto max-w-xl px-5 py-24 text-center">
      <h1 className="text-xl font-bold">مشکلی پیش آمد</h1>
      <p className="mt-3 text-sm leading-7 text-muted">
        اطلاعات در حال حاضر آماده نیست. لطفاً دوباره تلاش کنید.
      </p>
      <button
        onClick={reset}
        className="mt-5 rounded-xl bg-brand px-5 py-3 text-sm font-bold text-on-brand"
      >
        تلاش دوباره
      </button>
    </main>
  );
}
